     1	/**
     2	 * HTTP entry: assigns a request id to every incoming request and hands it to
     3	 * the router. This is where the request id is born.
     4	 */
     5	import { randomUUID } from "node:crypto";
     6	import { Router, type RouteRequest, type RouteResponse } from "./router.ts";
     7	import { JobQueue } from "../jobs/JobQueue.ts";
     8	import type { Sink } from "../platform/logging/AppLogger.ts";
     9	
    10	export interface IncomingRequest {
    11	  readonly method: RouteRequest["method"];
    12	  readonly path: string;
    13	  readonly headers: Record<string, string | undefined>;
    14	  readonly body?: unknown;
    15	}
    16	
    17	export function createApp(queue: JobQueue = new JobQueue(), sink?: Sink): { handle(req: IncomingRequest): Promise<RouteResponse> } {
    18	  const router = new Router(sink)
    19	    .add("GET", "/health", (_req, log) => {
    20	      log.info("health check");
    21	      return { status: 200, body: { ok: true } };
    22	    })
    23	    .add("POST", "/reports", (req, log) => {
    24	      const id = queue.enqueue({ kind: "report", payload: req.body }, { requestId: req.requestId });
    25	      log.info("report queued", { jobId: id });
    26	      return { status: 202, body: { jobId: id } };
    27	    });
    28	
    29	  return {
    30	    async handle(req: IncomingRequest): Promise<RouteResponse> {
    31	      const requestId = req.headers["x-request-id"] ?? randomUUID();
    32	      return router.dispatch({ method: req.method, path: req.path, requestId, body: req.body });
    33	    },
    34	  };
    35	}
