     1	/**
     2	 * Background jobs. A job records the request id of the request that enqueued
     3	 * it. Running a job does not log anything yet.
     4	 */
     5	export interface Job {
     6	  readonly kind: string;
     7	  readonly payload: unknown;
     8	}
     9	
    10	export interface QueuedJob extends Job {
    11	  readonly id: string;
    12	  readonly requestId: string;
    13	  readonly enqueuedAt: number;
    14	}
    15	
    16	export type JobRunner = (job: QueuedJob) => Promise<void> | void;
    17	
    18	export class JobQueue {
    19	  readonly #jobs: QueuedJob[] = [];
    20	  #next = 1;
    21	
    22	  enqueue(job: Job, opts: { requestId: string }): string {
    23	    const id = `job-${this.#next++}`;
    24	    this.#jobs.push({ ...job, id, requestId: opts.requestId, enqueuedAt: Date.now() });
    25	    return id;
    26	  }
    27	
    28	  get size(): number {
    29	    return this.#jobs.length;
    30	  }
    31	
    32	  /** Runs every queued job in order. A failing job is dropped; the rest still run. */
    33	  async run(runner: JobRunner): Promise<{ ran: number; failed: number }> {
    34	    let ran = 0;
    35	    let failed = 0;
    36	    while (this.#jobs.length > 0) {
    37	      const job = this.#jobs.shift()!;
    38	      try {
    39	        await runner(job);
    40	        ran++;
    41	      } catch {
    42	        failed++;
    43	      }
    44	    }
    45	    return { ran, failed };
    46	  }
    47	}

